    public enum Effective: Codable, Hashable, Sendable {
        case allow(ConnectorPolicyEffectiveAllow)
        case deny(ConnectorPolicyEffectiveDeny)
        case denyAll(ConnectorPolicyEffectiveDenyAll)
        case unrestricted(ConnectorPolicyEffectiveUnrestricted)
        /// A kind this build does not know, kept as it arrived.
        case unknown(GatewayJSON)

        public init(from decoder: any Decoder) throws {
            let raw = try GatewayJSON(from: decoder)
            switch raw["mode"]?.stringValue {
            case "allow": self = .allow(try ConnectorPolicyEffectiveAllow(from: decoder))
            case "deny": self = .deny(try ConnectorPolicyEffectiveDeny(from: decoder))
            case "deny-all": self = .denyAll(try ConnectorPolicyEffectiveDenyAll(from: decoder))
            case "unrestricted": self = .unrestricted(try ConnectorPolicyEffectiveUnrestricted(from: decoder))
            default: self = .unknown(raw)
            }
        }

        public func encode(to encoder: any Encoder) throws {
            switch self {
            case .allow(let value): try value.encode(to: encoder)
            case .deny(let value): try value.encode(to: encoder)
            case .denyAll(let value): try value.encode(to: encoder)
            case .unrestricted(let value): try value.encode(to: encoder)
            case .unknown(let raw): try raw.encode(to: encoder)
            }
        }
    }

