    public enum GoalSnapshotWaitBarrier: Codable, Hashable, Sendable {
        case pid(WaitBarrierTarget)
        case session(WaitBarrierTarget)
        case until(WaitBarrierUntil)
        /// A kind this build does not know, kept as it arrived.
        case unknown(GatewayJSON)

        public init(from decoder: any Decoder) throws {
            let raw = try GatewayJSON(from: decoder)
            switch raw["type"]?.stringValue {
            case "pid": self = .pid(try WaitBarrierTarget(from: decoder))
            case "session": self = .session(try WaitBarrierTarget(from: decoder))
            case "until": self = .until(try WaitBarrierUntil(from: decoder))
            default: self = .unknown(raw)
            }
        }

        public func encode(to encoder: any Encoder) throws {
            switch self {
            case .pid(let value): try value.encode(to: encoder)
            case .session(let value): try value.encode(to: encoder)
            case .until(let value): try value.encode(to: encoder)
            case .unknown(let raw): try raw.encode(to: encoder)
            }
        }
    }

